DO $$ BEGIN CREATE TEMP TABLE IF NOT EXISTS _u AS SELECT s.id, s.supplier_id, s.doc_type, s.po_text, s.job_name, s.invoice_date, x.po_id, EXISTS (SELECT 1 FROM supplier_doc_pages p WHERE p.supplier_invoice_id = s.id) AS scanned FROM supplier_invoices s CROSS JOIN LATERAL (SELECT public._sinv_po(s) AS po_id) x LEFT JOIN purchase_orders po ON po.id = x.po_id WHERE po.job_id IS NULL; RAISE EXCEPTION 'PROBE4 %', (SELECT string_agg(t, '|') FROM (SELECT left(btrim(sp.name),10)||'='||count(*) t FROM _u JOIN suppliers sp ON sp.id=_u.supplier_id GROUP BY sp.name ORDER BY count(*) DESC LIMIT 9) z); END $$;
